import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.Arrays;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());long[] t = new long[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {t[i] = Long.parseLong(st.nextToken());}Arrays.sort(t);long currentTime = 0;int satisfiedCount = 0;for (int i = 0; i < n; i++) {if (t[i] >= currentTime) {satisfiedCount++;currentTime += t[i];}}System.out.println(satisfiedCount);}}